// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./IERC20.sol";

contract MockUSDRIF is IERC20 {
    string public constant name = "USD RIF";
    string public constant symbol = "USDRIF";
    uint8 public constant decimals = 18;
    uint256 public totalSupply;

    mapping(address => uint256) private balances;
    mapping(address => mapping(address => uint256)) private allowances;

    address public owner;

    constructor(uint256 _initialSupply) {
        owner = msg.sender;
        totalSupply = _initialSupply * 10**decimals;
        balances[msg.sender] = totalSupply;
        emit Transfer(address(0), msg.sender, totalSupply);
    }

    function balanceOf(address account) public view override returns (uint256) {
        return balances[account];
    }

    function transfer(address to, uint256 amount) public override returns (bool) {
        address owner = msg.sender;
        _transfer(owner, to, amount);
        return true;
    }

    function allowance(address owner, address spender) public view override returns (uint256) {
        return allowances[owner][spender];
    }

    function approve(address spender, uint256 amount) public override returns (bool) {
        address owner = msg.sender;
        _approve(owner, spender, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) public override returns (bool) {
        address spender = msg.sender;
        _spendAllowance(from, spender, amount);
        _transfer(from, to, amount);
        return true;
    }

    function _transfer(address from, address to, uint256 amount) internal {
        require(from != address(0), "ERC20: transfer from the zero address");
        require(to != address(0), "ERC20: transfer to the zero address");

        uint256 fromBalance = balances[from];
        require(fromBalance >= amount, "ERC20: transfer amount exceeds balance");
        unchecked {
            balances[from] = fromBalance - amount;
            balances[to] += amount;
        }

        emit Transfer(from, to, amount);
    }

    function _approve(address owner, address spender, uint256 amount) internal {
        require(owner != address(0), "ERC20: approve from the zero address");
        require(spender != address(0), "ERC20: approve to the zero address");

        allowances[owner][spender] = amount;
        emit Approval(owner, spender, amount);
    }

    function _spendAllowance(address owner, address spender, uint256 amount) internal {
        uint256 currentAllowance = allowance(owner, spender);
        if (currentAllowance != type(uint256).max) {
            require(currentAllowance >= amount, "ERC20: insufficient allowance");
            unchecked {
                _approve(owner, spender, currentAllowance - amount);
            }
        }
    }

    // Mint function for testing
    function mint(address to, uint256 amount) external {
        require(msg.sender == owner, "Only owner can mint");
        totalSupply += amount;
        balances[to] += amount;
        emit Transfer(address(0), to, amount);
    }

    // Faucet function for easy testing
    function faucet() external {
        uint256 amount = 1000 * 10**decimals; // 1000 USDRIF
        require(balances[owner] >= amount, "Insufficient faucet balance");

        balances[owner] -= amount;
        balances[msg.sender] += amount;
        emit Transfer(owner, msg.sender, amount);
    }
}

contracts/X402AccessControl.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./X402PaymentGateway.sol";

contract X402AccessControl {
    X402PaymentGateway public immutable paymentGateway;

    struct AccessRequest {
        bytes32 resourceId;
        address requester;
        uint256 timestamp;
        bool granted;
    }

    mapping(bytes32 => AccessRequest) public accessRequests;
    mapping(bytes32 => mapping(address => uint256)) public lastAccess;

    event AccessRequested(
        bytes32 indexed requestId,
        address indexed requester,
        bytes32 indexed resourceId
    );

    event AccessGranted(
        bytes32 indexed requestId,
        address indexed requester,
        bytes32 indexed resourceId,
        bytes32 paymentId
    );

    event AccessDenied(
        bytes32 indexed requestId,
        address indexed requester,
        bytes32 indexed resourceId,
        string reason
    );

    constructor(address _paymentGateway) {
        paymentGateway = X402PaymentGateway(_paymentGateway);
    }

    function requestAccess(
        bytes32 resourceId,
        bytes32 paymentId
    ) external returns (bytes32 requestId) {
        requestId = keccak256(
            abi.encodePacked(
                msg.sender,
                resourceId,
                block.timestamp,
                block.number
            )
        );

        accessRequests[requestId] = AccessRequest({
            resourceId: resourceId,
            requester: msg.sender,
            timestamp: block.timestamp,
            granted: false
        });

        emit AccessRequested(requestId, msg.sender, resourceId);

        if (paymentId != bytes32(0)) {
            _verifyAndGrantAccess(requestId, paymentId, resourceId);
        }

        return requestId;
    }

    function grantAccessWithPayment(
        bytes32 requestId,
        bytes32 paymentId
    ) external {
        AccessRequest storage request = accessRequests[requestId];
        require(request.requester == msg.sender, "Not your request");
        require(!request.granted, "Already granted");

        _verifyAndGrantAccess(requestId, paymentId, request.resourceId);
    }

    function _verifyAndGrantAccess(
        bytes32 requestId,
        bytes32 paymentId,
        bytes32 resourceId
    ) internal {
        (bool valid, address payer) = paymentGateway.verifyPayment(
            paymentId,
            resourceId,
            3600 // 1 hour validity
        );

        if (valid && payer == msg.sender) {
            accessRequests[requestId].granted = true;
            lastAccess[resourceId][msg.sender] = block.timestamp;

            emit AccessGranted(requestId, msg.sender, resourceId, paymentId);
        } else {
            emit AccessDenied(requestId, msg.sender, resourceId, "Invalid payment");
        }
    }

    function checkAccess(
        address user,
        bytes32 resourceId,
        uint256 validityPeriod
    ) external view returns (bool hasAccess) {
        uint256 lastAccessTime = lastAccess[resourceId][user];

        if (lastAccessTime == 0) {
            return false;
        }

        return block.timestamp <= lastAccessTime + validityPeriod;
    }

    function hasValidAccess(
        address user,
        bytes32 resourceId
    ) external view returns (bool) {
        return this.checkAccess(user, resourceId, 3600); // Default 1 hour
    }
}

contracts/X402PaymentGateway.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./IERC20.sol";

contract X402PaymentGateway {
    IERC20 public immutable usdrifToken;

    struct PaymentProof {
        address payer;
        address recipient;
        uint256 amount;
        uint256 timestamp;
        bytes32 resourceId;
        bool verified;
    }

    struct ServiceConfig {
        address recipient;
        uint256 price;
        uint256 validityDuration;
        bool active;
    }

    mapping(bytes32 => PaymentProof) public payments;
    mapping(bytes32 => ServiceConfig) public services;
    mapping(address => bool) public authorizedServices;

    address public owner;
    uint256 public constant MIN_PAYMENT = 1e15; // 0.001 USDRIF

    event PaymentMade(
        bytes32 indexed paymentId,
        address indexed payer,
        address indexed recipient,
        uint256 amount,
        bytes32 resourceId
    );

    event ServiceRegistered(
        bytes32 indexed serviceId,
        address indexed recipient,
        uint256 price
    );

    event AccessGranted(
        bytes32 indexed paymentId,
        address indexed payer,
        bytes32 indexed resourceId
    );

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    modifier onlyAuthorizedService() {
        require(authorizedServices[msg.sender], "Not authorized service");
        _;
    }

    constructor(address _usdrifToken) {
        usdrifToken = IERC20(_usdrifToken);
        owner = msg.sender;
    }

    function registerService(
        bytes32 serviceId,
        address recipient,
        uint256 price,
        uint256 validityDuration
    ) external {
        require(price >= MIN_PAYMENT, "Price too low");
        require(recipient != address(0), "Invalid recipient");

        services[serviceId] = ServiceConfig({
            recipient: recipient,
            price: price,
            validityDuration: validityDuration,
            active: true
        });

        emit ServiceRegistered(serviceId, recipient, price);
    }

    function makePayment(
        bytes32 serviceId,
        bytes32 resourceId
    ) external returns (bytes32 paymentId) {
        return makePaymentFrom(msg.sender, serviceId, resourceId);
    }

    function makePaymentFrom(
        address payer,
        bytes32 serviceId,
        bytes32 resourceId
    ) public returns (bytes32 paymentId) {
        ServiceConfig memory service = services[serviceId];
        require(service.active, "Service not active");

        paymentId = keccak256(
            abi.encodePacked(
                payer,
                serviceId,
                resourceId,
                block.timestamp,
                block.number
            )
        );

        require(!payments[paymentId].verified, "Payment already exists");

        bool success = usdrifToken.transferFrom(
            payer,
            service.recipient,
            service.price
        );
        require(success, "Payment failed");

        payments[paymentId] = PaymentProof({
            payer: payer,
            recipient: service.recipient,
            amount: service.price,
            timestamp: block.timestamp,
            resourceId: resourceId,
            verified: true
        });

        emit PaymentMade(paymentId, payer, service.recipient, service.price, resourceId);
        emit AccessGranted(paymentId, payer, resourceId);

        return paymentId;
    }

    function verifyPayment(
        bytes32 paymentId,
        bytes32 resourceId,
        uint256 validityDuration
    ) external view returns (bool valid, address payer) {
        PaymentProof memory payment = payments[paymentId];

        if (!payment.verified) {
            return (false, address(0));
        }

        if (payment.resourceId != resourceId) {
            return (false, address(0));
        }

        if (validityDuration == 0 ||
            block.timestamp > payment.timestamp + validityDuration) {
            return (false, address(0));
        }

        return (true, payment.payer);
    }

    function verifyPaymentForService(
        bytes32 paymentId,
        bytes32 serviceId
    ) external view returns (bool valid, address payer) {
        ServiceConfig memory service = services[serviceId];
        PaymentProof memory payment = payments[paymentId];

        return this.verifyPayment(paymentId, payment.resourceId, service.validityDuration);
    }

    function generateResourceId(
        string memory resource,
        address requester
    ) public pure returns (bytes32) {
        return keccak256(abi.encodePacked(resource, requester));
    }

    function generateServiceId(string memory serviceName) public pure returns (bytes32) {
        return keccak256(abi.encodePacked(serviceName));
    }

    function authorizeService(address service, bool authorized) external onlyOwner {
        authorizedServices[service] = authorized;
    }

    function updateServiceStatus(bytes32 serviceId, bool active) external {
        ServiceConfig storage service = services[serviceId];
        require(
            service.recipient == msg.sender ||
            msg.sender == owner ||
            authorizedServices[msg.sender],
            "Not authorized"
        );
        service.active = active;
    }

    function updateServicePrice(bytes32 serviceId, uint256 newPrice) external {
        ServiceConfig storage service = services[serviceId];
        require(
            service.recipient == msg.sender ||
            msg.sender == owner ||
            authorizedServices[msg.sender],
            "Not authorized"
        );
        require(newPrice >= MIN_PAYMENT, "Price too low");
        service.price = newPrice;
    }

    function getPaymentInfo(bytes32 paymentId) external view returns (
        address payer,
        address recipient,
        uint256 amount,
        uint256 timestamp,
        bytes32 resourceId,
        bool verified
    ) {
        PaymentProof memory payment = payments[paymentId];
        return (
            payment.payer,
            payment.recipient,
            payment.amount,
            payment.timestamp,
            payment.resourceId,
            payment.verified
        );
    }

    function getServiceInfo(bytes32 serviceId) external view returns (
        address recipient,
        uint256 price,
        uint256 validityDuration,
        bool active
    ) {
        ServiceConfig memory service = services[serviceId];
        return (service.recipient, service.price, service.validityDuration, service.active);
    }
}

contracts/X402ServiceRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./X402PaymentGateway.sol";

contract X402ServiceRegistry {
    X402PaymentGateway public immutable paymentGateway;

    struct Service {
        string name;
        string description;
        address owner;
        uint256 price;
        uint256 validityDuration;
        string[] endpoints;
        bool active;
        uint256 totalPayments;
        uint256 totalRevenue;
    }

    struct Subscription {
        address subscriber;
        bytes32 serviceId;
        uint256 expiresAt;
        bool active;
    }

    mapping(bytes32 => Service) public services;
    mapping(address => bytes32[]) public servicesByOwner;
    mapping(bytes32 => mapping(address => Subscription)) public subscriptions;

    bytes32[] public allServices;

    event ServiceCreated(
        bytes32 indexed serviceId,
        address indexed owner,
        string name,
        uint256 price
    );

    event ServiceUpdated(
        bytes32 indexed serviceId,
        uint256 newPrice,
        bool active
    );

    event SubscriptionCreated(
        bytes32 indexed serviceId,
        address indexed subscriber,
        uint256 expiresAt
    );

    constructor(address _paymentGateway) {
        paymentGateway = X402PaymentGateway(_paymentGateway);
    }

    function createService(
        string memory name,
        string memory description,
        uint256 price,
        uint256 validityDuration,
        string[] memory endpoints
    ) external returns (bytes32 serviceId) {
        serviceId = keccak256(abi.encodePacked(name, msg.sender, block.timestamp));

        services[serviceId] = Service({
            name: name,
            description: description,
            owner: msg.sender,
            price: price,
            validityDuration: validityDuration,
            endpoints: endpoints,
            active: true,
            totalPayments: 0,
            totalRevenue: 0
        });

        servicesByOwner[msg.sender].push(serviceId);
        allServices.push(serviceId);

        // Register with payment gateway
        paymentGateway.registerService(serviceId, msg.sender, price, validityDuration);

        emit ServiceCreated(serviceId, msg.sender, name, price);
        return serviceId;
    }

    function subscribeToService(
        bytes32 serviceId,
        bytes32 resourceId
    ) external returns (bytes32 paymentId) {
        Service storage service = services[serviceId];
        require(service.active, "Service not active");

        paymentId = paymentGateway.makePaymentFrom(msg.sender, serviceId, resourceId);

        subscriptions[serviceId][msg.sender] = Subscription({
            subscriber: msg.sender,
            serviceId: serviceId,
            expiresAt: block.timestamp + service.validityDuration,
            active: true
        });

        service.totalPayments++;
        service.totalRevenue += service.price;

        emit SubscriptionCreated(serviceId, msg.sender, block.timestamp + service.validityDuration);
        return paymentId;
    }

    function updateService(
        bytes32 serviceId,
        uint256 newPrice,
        bool active
    ) external {
        Service storage service = services[serviceId];
        require(service.owner == msg.sender, "Not service owner");

        service.price = newPrice;
        service.active = active;

        paymentGateway.updateServiceStatus(serviceId, active);
        paymentGateway.updateServicePrice(serviceId, newPrice);

        emit ServiceUpdated(serviceId, newPrice, active);
    }

    function addEndpoint(bytes32 serviceId, string memory endpoint) external {
        Service storage service = services[serviceId];
        require(service.owner == msg.sender, "Not service owner");

        service.endpoints.push(endpoint);
    }

    function hasActiveSubscription(
        address subscriber,
        bytes32 serviceId
    ) external view returns (bool) {
        Subscription memory sub = subscriptions[serviceId][subscriber];
        return sub.active && block.timestamp < sub.expiresAt;
    }

    function getServiceInfo(bytes32 serviceId) external view returns (
        string memory name,
        string memory description,
        address owner,
        uint256 price,
        uint256 validityDuration,
        bool active,
        uint256 totalPayments,
        uint256 totalRevenue
    ) {
        Service memory service = services[serviceId];
        return (
            service.name,
            service.description,
            service.owner,
            service.price,
            service.validityDuration,
            service.active,
            service.totalPayments,
            service.totalRevenue
        );
    }

    function getServiceEndpoints(bytes32 serviceId) external view returns (string[] memory) {
        return services[serviceId].endpoints;
    }

    function getServicesByOwner(address owner) external view returns (bytes32[] memory) {
        return servicesByOwner[owner];
    }

    function getAllServices() external view returns (bytes32[] memory) {
        return allServices;
    }

    function getSubscriptionInfo(
        bytes32 serviceId,
        address subscriber
    ) external view returns (
        address sub,
        uint256 expiresAt,
        bool active
    ) {
        Subscription memory subscription = subscriptions[serviceId][subscriber];
        return (subscription.subscriber, subscription.expiresAt, subscription.active);
    }
}

